),
faltando AS (
  SELECT DISTINCT it->>'insumo' AS insumo
  FROM entrada, jsonb_array_elements(entrada.lista) f, jsonb_array_elements(f->'recheio') it
  WHERE NOT EXISTS (SELECT 1 FROM ins WHERE ins.nome = it->>'insumo')
),
novas AS (
  SELECT COALESCE(jsonb_agg(
    f || jsonb_build_object(
      'id', gen_random_uuid()::text,
      'recheio', (
        SELECT COALESCE(jsonb_agg(
          jsonb_strip_nulls((it - 'insumo') || jsonb_build_object('id', gen_random_uuid()::text, 'tipo', 'insumo', 'refId', ins.id))
          ORDER BY o
        ), '[]'::jsonb)
        FROM jsonb_array_elements(f->'recheio') WITH ORDINALITY AS x(it, o)
        JOIN ins ON ins.nome = it->>'insumo'
      )
    )
  ), '[]'::jsonb) AS lista
  FROM entrada, jsonb_array_elements(entrada.lista) f
),
acai AS (
  SELECT id FROM ins WHERE nome = 'Açaí natural'
),
bases_novas AS (
  SELECT jsonb_agg(jsonb_build_object(
    'id', n.id,
    'nome', n.nome,
    'itens', (
      SELECT jsonb_agg(CASE WHEN it->>'refId' = (SELECT id FROM acai) THEN it || jsonb_build_object('qtd', n.acai) ELSE it END)
      FROM jsonb_array_elements(b->'itens') it
    )
  )) AS lista
  FROM r,
       jsonb_array_elements(r.dados->'bases') b,
       (VALUES ('base-770', 'base-770-combo', 'Base combo 770ml', 700), ('base-1l', 'base-pote-recheado', 'Base pote recheado 1 litro', 1000)) AS n(origem, id, nome, acai)
  WHERE b->>'id' = n.origem
),
bases_mantidas AS (
  SELECT COALESCE(jsonb_agg(b), '[]'::jsonb) AS lista
  FROM r, jsonb_array_elements(COALESCE(r.dados->'bases', '[]'::jsonb)) b
  WHERE b->>'id' NOT IN ('base-770-combo', 'base-pote-recheado')
),
mantidas AS (
  SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) AS lista
