UPDATE public.financeiro_maisacai f
SET dados = f.dados || jsonb_build_object(
      'fichas', mantidas.lista || novas.lista,
      'bases', bases_mantidas.lista || bases_novas.lista
    ),
    updated_at = now()
FROM mantidas, novas, bases_mantidas, bases_novas
WHERE f.id = 'principal'
  AND bases_novas.lista IS NOT NULL
  AND jsonb_array_length(bases_novas.lista) = 2
  AND NOT EXISTS (SELECT 1 FROM faltando);

-- Conferência 1: deve vir VAZIO. Se aparecer algum insumo, ele não existe no Financeiro e nada foi gravado.
WITH ins AS (
  SELECT i->>'nome' AS nome FROM public.financeiro_maisacai, jsonb_array_elements(dados->'insumos') i WHERE id = 'principal'
)
SELECT n AS insumo_que_falta
FROM unnest(ARRAY['Abacaxi', 'Amendoim', 'Açaí natural', 'Banana', 'Bis extra ao leite', 'Bis extra oreo', 'Bolacha maisena triturada', 'Calda de morango', 'Chocoball', 'Cobertura de chocolate', 'Confete', 'Creme de avelã', 'Danoninho', 'Doce de leite', 'Granola', 'Kinder barrinha', 'Kinder bueno ao leite', 'Kinder bueno white', 'Kit kat ao leite', 'Kit kat white', 'Kiwi importado', 'Leite condensado', 'Leite em pó', 'Mel', 'Morango', 'Mousse de ninho', 'Ovomaltine', 'Paçoca', 'Uva verde s/ semente']) n
WHERE n NOT IN (SELECT nome FROM ins);

-- Conferência 3: as duas bases dos combos com 700 g e 1000 g de açaí
SELECT b->>'nome' AS base, it->>'qtd' AS acai_g
FROM public.financeiro_maisacai, jsonb_array_elements(dados->'bases') b, jsonb_array_elements(b->'itens') it
WHERE id = 'principal' AND b->>'id' IN ('base-770-combo', 'base-pote-recheado')
  AND it->>'refId' = (SELECT i->>'id' FROM public.financeiro_maisacai, jsonb_array_elements(dados->'insumos') i WHERE id = 'principal' AND i->>'nome' = 'Açaí natural');

